     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more points.
     */
    default @Nullable Integer membershipLevel(@Nullable Owner owner) {
        Integer points = membershipPoints(owner);
        if (points == null) {
            return null;
        }
        if (points <= 1) {
            return 1;
        }
        if (points <= 3) {
            return 2;
        }
        if (points <= 5) {
            return 3;
        }
        return 4;
    }

